package com.delivery.web_bff.infrastructure.proxy;
import com.delivery.web_bff.application.api.Ports; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient;
@Component public final class GatewayProxyAdapter implements Ports.ProxyForwarding { private final RestClient gateway; public GatewayProxyAdapter(RestClient gateway){this.gateway=gateway;}
 public Ports.ForwardedResponse forward(Ports.HttpVerb method,String path,String query,Map<String,List<String>> headers,byte[] body,String bearer){String target=query==null||query.isBlank()?path:path+"?"+query; HttpMethod http=HttpMethod.valueOf(method.name()); return gateway.method(http).uri(URI.create(target)).headers(h->{headers.forEach((k,v)->h.put(k,List.copyOf(v)));h.setBearerAuth(bearer);h.remove(HttpHeaders.COOKIE);h.remove(HttpHeaders.HOST);}).body(body).exchange((req,res)->{Map<String,List<String>> out=new HashMap<>();for(String n:List.of(HttpHeaders.CONTENT_TYPE,HttpHeaders.CACHE_CONTROL,HttpHeaders.ETAG,HttpHeaders.LAST_MODIFIED,HttpHeaders.LOCATION,"X-Correlation-ID","Retry-After")){if(res.getHeaders().containsKey(n))out.put(n,List.copyOf(res.getHeaders().get(n)));}return new Ports.ForwardedResponse(res.getStatusCode().value(),out,res.getBody().readAllBytes());});}
}
